const input = $input.first().json;
const body = input.body || input;

const errors = [];

const validProviders = ['openai', 'claude', 'gemini', 'mistral'];
const defaultModels = {
  openai: 'gpt-4o',
  claude: 'claude-sonnet-4-20250514',
  gemini: 'gemini-2.5-flash',
  mistral: 'mistral-large-latest'
};

const urlPattern = /^https?:\/\/[^\s]+$/i;

if (!body.urls || !Array.isArray(body.urls) || body.urls.length === 0) {
  errors.push('Missing required parameter: urls (array of URLs)');
} else if (body.urls.length > 5) {
  errors.push('Maximum 5 URLs allowed per request');
} else {
  for (const url of body.urls) {
    if (typeof url !== 'string' || !urlPattern.test(url.trim())) {
      errors.push(`Invalid URL: ${url}`);
    }
  }
}

const provider = body.provider || 'claude';

if (!validProviders.includes(provider)) {
  errors.push(`Invalid provider: '${provider}'. Valid options: ${validProviders.join(', ')}`);
}

if (provider === 'openai' && !body.openai_api_key) errors.push('Missing openai_api_key');
if (provider === 'claude' && !body.anthropic_api_key) errors.push('Missing anthropic_api_key');
if (provider === 'gemini' && !body.google_api_key) errors.push('Missing google_api_key');
if (provider === 'mistral' && !body.mistral_api_key) errors.push('Missing mistral_api_key');

if (errors.length > 0) {
  return [{ json: { valid: false, error: { code: 400, message: errors.join(', '), status: 'BAD_REQUEST' } } }];
}

return [{
  json: {
    valid: true,
    urls: body.urls,
    query: body.query || 'Extract all relevant information from this content',
    provider,
    model: body.model || defaultModels[provider],
    openai_api_key: body.openai_api_key,
    anthropic_api_key: body.anthropic_api_key,
    google_api_key: body.google_api_key,
    mistral_api_key: body.mistral_api_key,
    output_schema: body.output_schema || null,
    options: { language: body.options?.language || 'fr', include_sources: body.options?.include_sources !== false },
    callback_url: body.callback_url || null,
    job_id: body.job_id || null,
    start_time: Date.now()
  }
}];

const data = $input.first().json;

// Create one item per URL, carrying context
return data.urls.map(url => ({
  json: {
    url,
    context: {
      ...data,
      job_id: data.job_id || $execution.id
    }
  }
}));

const items = $input.all();
const results = [];

for (const item of items) {
  const url = item.json.url || item.json.context?.url;
  const context = item.json.context;

  // Check if fetch was successful
  if (item.json.error || item.json.statusCode >= 400) {
    results.push({
      url,
      success: false,
      error: item.json.error?.message || `HTTP ${item.json.statusCode}`,
      content: null
    });
    continue;
  }

  // Get HTML content
  let html = '';
  if (typeof item.json.body === 'string') {
    html = item.json.body;
  } else if (item.json.data) {
    html = typeof item.json.data === 'string' ? item.json.data : JSON.stringify(item.json.data);
  }

  // Basic HTML to text
  let text = html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (text.length > 15000) {
    text = text.substring(0, 15000) + '... [truncated]';
  }

  results.push({
    url,
    success: text.length > 100,
    error: text.length <= 100 ? 'Content too short or empty' : null,
    content: text.length > 100 ? text : null
  });
}

// Get context from first item
const firstContext = items[0]?.json?.context || $('Split URLs').first().json.context;

return [{
  json: {
    context: firstContext,
    fetched_urls: results,
    successful_count: results.filter(r => r.success).length
  }
}];

const data = $input.first().json;
const ctx = data.context;

// Build content from fetched URLs
const contentParts = data.fetched_urls
  .filter(u => u.success)
  .map(u => `=== Content from ${u.url} ===\n${u.content}`)
  .join('\n\n');

let systemPrompt = `Tu es un expert en extraction de données structurées. Analyse le contenu web fourni.\n\nRègles:\n1. Extrais uniquement les informations présentes\n2. Si une info n'est pas disponible, utilise null\n3. Réponds en ${ctx.options.language === 'fr' ? 'français' : 'anglais'}`;

if (ctx.output_schema) {
  systemPrompt += `\n\nSchéma de sortie:\n${JSON.stringify(ctx.output_schema.input_schema || ctx.output_schema, null, 2)}`;
}

const userPrompt = `${ctx.query}\n\n${contentParts}`;

let llm_url, llm_headers, llm_body;

switch (ctx.provider) {
  case 'claude':
    llm_url = 'https://api.anthropic.com/v1/messages';
    llm_headers = { 'x-api-key': ctx.anthropic_api_key, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' };
    llm_body = { model: ctx.model, max_tokens: 4096, messages: [{ role: 'user', content: systemPrompt + '\n\n' + userPrompt }] };
    break;
  case 'openai':
    llm_url = 'https://api.openai.com/v1/chat/completions';
    llm_headers = { 'Authorization': 'Bearer ' + ctx.openai_api_key, 'Content-Type': 'application/json' };
    llm_body = { model: ctx.model, max_tokens: 4096, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }] };
    if (ctx.output_schema) llm_body.response_format = { type: 'json_object' };
    break;
  case 'gemini':
    llm_url = `https://generativelanguage.googleapis.com/v1beta/models/${ctx.model}:generateContent?key=${ctx.google_api_key}`;
    llm_headers = { 'Content-Type': 'application/json' };
    llm_body = { contents: [{ parts: [{ text: systemPrompt + '\n\n' + userPrompt }] }], generationConfig: { maxOutputTokens: 4096 } };
    break;
  case 'mistral':
    llm_url = 'https://api.mistral.ai/v1/chat/completions';
    llm_headers = { 'Authorization': 'Bearer ' + ctx.mistral_api_key, 'Content-Type': 'application/json' };
    llm_body = { model: ctx.model, max_tokens: 4096, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }] };
    if (ctx.output_schema) llm_body.response_format = { type: 'json_object' };
    break;
}

return [{
  json: {
    ...data,
    llm_url,
    llm_headers,
    llm_body: JSON.stringify(llm_body)
  }
}];

const input = $input.first().json;
const prevData = $('Prepare LLM Body').first().json;
const ctx = prevData.context;
const processingTime = Date.now() - ctx.start_time;

// Check for LLM error
if (input.error) {
  return [{
    json: {
      success: false,
      error: { code: 'LLM_ERROR', message: input.error.message || JSON.stringify(input.error) },
      context: ctx,
      fetched_urls: prevData.fetched_urls,
      processing_time_ms: processingTime
    }
  }];
}

// Extract text based on provider
let extractedText = '';
switch (ctx.provider) {
  case 'claude':
    extractedText = input.content?.[0]?.text || '';
    break;
  case 'openai':
  case 'mistral':
    extractedText = input.choices?.[0]?.message?.content || '';
    break;
  case 'gemini':
    extractedText = input.candidates?.[0]?.content?.parts?.[0]?.text || '';
    break;
}

// Parse JSON if schema provided
let parsedResult = extractedText;
if (ctx.output_schema) {
  try {
    const jsonMatch = extractedText.match(/\{[\s\S]*\}/);
    if (jsonMatch) parsedResult = JSON.parse(jsonMatch[0]);
  } catch (e) { /* keep as text */ }
}

return [{
  json: {
    success: true,
    data: {
      extracted: parsedResult,
      sources: ctx.options.include_sources ? prevData.fetched_urls.map(u => ({ url: u.url, success: u.success, error: u.error })) : undefined
    },
    meta: {
      provider: ctx.provider,
      model: ctx.model,
      urls_fetched: prevData.fetched_urls.length,
      urls_successful: prevData.successful_count,
      tokens_used: input.usage?.total_tokens || (input.usage?.input_tokens || 0) + (input.usage?.output_tokens || 0),
      processing_time_ms: processingTime
    },
    context: ctx,
    fetched_urls: prevData.fetched_urls
  }
}];

const data = $input.first().json;
const ctx = data.context;

const callback = {
  job_id: ctx.job_id,
  success: data.success,
  result: data.success ? data.data : null,
  metrics: data.meta || { urls_fetched: data.fetched_urls?.length || 0 },
  error: data.error || null
};

// HMAC signature (RFC-040)
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify(callback);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{
  json: {
    callback_url: ctx.callback_url,
    payload,
    signature
  }
}];

